ee:variables.ee:set-variable:
%dw 2.0
output application/java
---
//"2025-06-23T00:00:00"
//now() as DateTime as String {format: "yyyy-MM-dd'T'00:00:00"}

(now() as DateTime >> "America/Los_Angeles") as String {format: "yyyy-MM-dd'T'00:00:00"}
//"2025-09-22T15:00:00

%dw 2.0
output application/java
---
//"2025-06-23T00:00:00"
//now() as DateTime as String {format: "yyyy-MM-dd'T'HH:mm:ss"}


(now() as DateTime >> "America/Los_Angeles") as String {format: "yyyy-MM-dd'T'HH:mm:ss"}

%dw 2.0
output application/json
var rows = payload.Data.Rows
var weeklyCodes = ["BAZ", "BCW", "BEI", "NBB"]
var biweeklyCodes = ["BCS", "Temp"]
---
//$.Employee_HireDate <= vars.currentTime and 
rows filter($.Employee_HireDate >= vars.currentdate and $.EmploymentStatus_ShortName != "Pre-Start" and $.Employee_TerminationDate == null) map (row) -> {
//rows filter($.EmployeeEmploymentStatus_EmployeeNumber == '152233' and $.EmploymentStatus_ShortName != "Pre-Start" and $.Employee_TerminationDate == null) map (row) -> {
  Company_Code: row.CompanyCode default "",
  Employee_Code: row.EmployeeEmploymentStatus_EmployeeNumber default "",
  Alpha_Sort: (if (row.Employee_FirstName != null) ( 
  (row.Employee_FirstName )[0 to 0]) else "" ) ++ upper(  
   if (row.Employee_LastName != null)
    (row.Employee_LastName )[0 to 0] else "" ),
   First_Name: row.Employee_FirstName default "",
  Middle_Name: if ((row.Employee_MiddleName as String default "") == "") "" else row.Employee_MiddleName,
  Last_Name: row.Employee_LastName default "",
  Employee_Suffix: "",
//Worker_Comp_Code: row.PRWCBCode_WCBCode default "",
Worker_Comp_Code: row.WorkersCompCode default "",
        Department_Code: row.LedgerCode default "",
Employment_Status: 
    if ((row.EmploymentStatus_ShortName as String default "") == "Active") "A"
    else if ((row.EmploymentStatus_ShortName as String default "") == "LOA") "L"
    else if ((row.EmploymentStatus_ShortName as String default "") == "Terminated") "Z"
    else if ((row.EmploymentStatus_ShortName as String default "") == "Severance") "Z"
    else "",
// Pay_Type: upper(
   // //if (row.PayType_LongName as String default "" contains "hourly") "H"
   // else if (row.PayType_LongName as String default "" contains "salary") "S"
  //  else if (row.PayType_LongName as String default "" contains "commission") "C"
  //  else if (row.PayType_LongName as String default "" contains "overtime") "O"
  //  else "H"
  //),
  Pay_Type: "H",
  Pay_Frequency_Flag: 
    if (weeklyCodes contains (row.PayGroup_XRefCode as String default "")) "W"
    else if (biweeklyCodes contains (row.PayGroup_XRefCode as String default "")) "B"
    else (row.PayGroup_XRefCode as String default ""),
Hourly_Rate: 
 if ((row.PayRate as Number default 0) > 0) 
   (row.PayRate as Number) as String {format: "##0.0"}
 else 
    "0.00",
  Fed_Tax_Code: "US",
Subject_to_Fed_Tax: if (row.EmployeeFederalTaxInfo_IsTaxExempt == "True") "E" else "T",
Subject_to_FICA_Fed:  "T",
Subject_to_FUTA_Fed:  "T",
Fed_Filing_Status: row.FederalFilingStatus as String default "" ,
State_Tax_Code: row.StateTaxStateCode  default "",
Subject_to_State_Tax: if (row.StateTaxIsTaxExempt == "True") "E" else "T",
Subject_to_SDI_State:  "T" ,
Subject_to_SUTA_State:  "T" ,
State_Filing_Status : row.StateFilingStatus as String default "",
Hire_Date_List1: (row.Employee_HireDate as DateTime)  as String {format: "MM/dd/yyyy"} default "",
  Termination_Date_List3: (row.Employee_TerminationDate as DateTime) as String {format: "MM/dd/yyyy"} default "",
  Employee_Place_Birth: row.Employee_BirthState default "",
Employee_Veteran_Stat: 
  if ((row.VeteransStatus as String default "") == "Disabled Veteran") "D"
  else if ((row.VeteransStatus) == "Armed Forces Service Medal Veteran") "A"
  else if ((row.VeteransStatus) == "Disabled Armed Forces") "M"
  else if ((row.VeteransStatus) == "Other Protected Veteran") "O"
  else if ((row.VeteransStatus) == "Disabled Other Protected Veteran") "P"
  else "N",
   Legal_First_Name: row.Employee_FirstName default "",
   Legal_Middle_Name: if ((row.Employee_MiddleName as String default "") == "")   "" else row.Employee_MiddleName,
  Legal_Last_Name: row.Employee_LastName default "",
  Legal_Suffix: row.Employee_Suffix default "",
 // Effective_Date: row.EffectivePayDate default ""
  //Employee_Citizenship: row.PersonAddress_CountryCode default "",
 // Employee_Driver_License_Class: row.DriverLicenseClass default "",
 //Employee_Driver_License_State: row.IdentificationPlaceofIssue default "",
   // Employee_Telephone_Memo : row.DenormEmployeeContact_HomePhone default "",
   //Authorization_ID: "DayforceHRsync", 
  //GUID: "e138d503-8ff1-4a39-9533-439d7c9a99e2",
  //Emp_Foreign: if (row.Employee_TaxExempt != null) "Y" else "N",
}

%dw 2.0
output application/json
var rows = payload.Data.Rows
var weeklyCodes = ["BAZ", "BCW", "BEI", "NBB"]
var biweeklyCodes = ["BCS", "Temp"]
---
//rows filter($.EmployeeEmploymentStatus_EmployeeNumber == '152233' and $.EmploymentStatus_ShortName != "Pre-Start" ) map (row) -> {
rows filter($.EmploymentStatus_ShortName != "Pre-Start" ) map (row) -> {
  Company_Code: row.CompanyCode default "",
  Employee_Code: row.EmployeeEmploymentStatus_EmployeeNumber default "",
  Alpha_Sort: (if (row.Employee_FirstName != null) ( 
  (row.Employee_FirstName )[0 to 0]) else "" ) ++ upper(  
   if (row.Employee_LastName != null)
    (row.Employee_LastName )[0 to 0] else "" ),
   First_Name: row.Employee_FirstName default "",
  Middle_Name: if ((row.Employee_MiddleName as String default "") == "") "" else row.Employee_MiddleName,
  Last_Name: row.Employee_LastName default "",
  Employee_Suffix: row.Employee_Suffix default "",
Worker_Comp_Code: row.WorkersCompCode default "",
        Department_Code: row.LedgerCode default "",
Employment_Status: 
    if ((row.EmploymentStatus_ShortName as String default "") == "Active") "A"
    else if ((row.EmploymentStatus_ShortName as String default "") == "LOA") "L"
    else if ((row.EmploymentStatus_ShortName as String default "") == "Terminated") "Z"
    else if ((row.EmploymentStatus_ShortName as String default "") == "Severance") "Z"
    else "",
    // Pay_Type: upper(
   // //if (row.PayType_LongName as String default "" contains "hourly") "H"
   // else if (row.PayType_LongName as String default "" contains "salary") "S"
  //  else if (row.PayType_LongName as String default "" contains "commission") "C"
  //  else if (row.PayType_LongName as String default "" contains "overtime") "O"
  //  else "H"
  //),
  Pay_Type: "H",
  Pay_Frequency_Flag: 
    if (weeklyCodes contains (row.PayGroup_XRefCode as String default "")) "W"
    else if (biweeklyCodes contains (row.PayGroup_XRefCode as String default "")) "B"
    else (row.PayGroup_XRefCode as String default ""),
//Hourly_Rate: 
 // if ((row.PayRate as Number default 0) > 0) 
   // (row.PayRate as Number) as String {format: "##0.0"}
  //else 
   // "0.00",
  Fed_Tax_Code: "US",
Subject_to_Fed_Tax: if (row.EmployeeFederalTaxInfo_IsTaxExempt == "True") "E" else "T",
Subject_to_FICA_Fed:  "T",
Subject_to_FUTA_Fed:  "T",
Fed_Filing_Status: row.FederalFilingStatus as String default "", 
State_Tax_Code: row.StateTaxStateCode,
Subject_to_State_Tax: if (row.StateTaxIsTaxExempt == "True") "E" else "T",
Subject_to_SDI_State:  "T" ,
Subject_to_SUTA_State:  "T" ,
State_Filing_Status : row.StateFilingStatus as String default "",
Hire_Date_List1: (row.Employee_HireDate as DateTime)  as String {format: "MM/dd/yyyy"} default null,
  Termination_Date_List3: (row.Employee_TerminationDate as DateTime) as String {format: "MM/dd/yyyy"} default "",
  Employee_Place_Birth: row.Employee_BirthState  default "",
Employee_Veteran_Stat: 
  if ((row.VeteransStatus as String default "") == "Disabled Veteran") "D"
  else if ((row.VeteransStatus) == "Armed Forces Service Medal Veteran") "A"
  else if ((row.VeteransStatus) == "Disabled Armed Forces") "M"
  else if ((row.VeteransStatus) == "Other Protected Veteran") "O"
  else if ((row.VeteransStatus) == "Disabled Other Protected Veteran") "P"
  else "N",
 // Employee_Citizenship: row.PersonAddress_CountryCode  default "",
  Employee_Driver_License_Class: row.DriverLicenseClass default "",
   Legal_First_Name: row.Employee_FirstName default "",
   Legal_Middle_Name: if ((row.Employee_MiddleName as String default "") == "")   "" else row.Employee_MiddleName,
  Legal_Last_Name: row.Employee_LastName default "",
  Legal_Suffix: row.Employee_Suffix default "",
// Effective_Date: row.EffectivePayDate default ""
 //Employee_Driver_License_State: row.IdentificationPlaceofIssue default "",
  //  Employee_Telephone_Memo : row.DenormEmployeeContact_HomePhone default "",
   //Authorization_ID: "DayforceHRsync", 
  //GUID: "e138d503-8ff1-4a39-9533-439d7c9a99e2",
  //Emp_Foreign: if (row.Employee_TaxExempt != null) "Y" else "N",
}

%dw 2.0
output application/json
var rows = payload.Data.Rows
---
rows filter($.EmploymentStatus_ShortName != "Pre-Start") map (row) -> {
//rows filter($.EmployeeEmploymentStatus_EmployeeNumber == '152233' and $.EmploymentStatus_ShortName != "Pre-Start") map (row) -> {
	Company_Code: row.CompanyCode,
	Employee_Code: row.EmployeeEmploymentStatus_EmployeeNumber,
	Alpha_Sort: (if ( row.Employee_FirstName != null ) ((row.Employee_FirstName)[0 to 0]) else "") ++ upper(  
   if ( row.Employee_LastName != null ) (row.Employee_LastName)[0 to 0] else "" ),
	Emergency_Contact: row.EmergencyContact default "",
	Emergency_Phone: row.EmergencyContactPhoneNumber default "",
	Emergency_Relationship: row.Contact1Relationshiptemp default "",
Worker_Comp_Code: row.WorkersCompCode default "",
	//row.PRWCBCode_WCBCode,
	Department_Code: row.LedgerCode,
	Sex: row.Employee_Gender,
	Social_Security: row.Employee_SocialSecurityNumber,
	Birth_Date_List4: (row.Employee_BirthDate as DateTime)  as String {
		format: "MM/dd/yyyy"
	} default null,
	Hire_Date_List1: (row.Hire_Date_List1 as DateTime)  as String {
		format: "MM/dd/yyyy"
	} default null,
	Termination_Date_List3: (row.Employee_TerminationDate as DateTime)  as String {
		format: "MM/dd/yyyy"
	} default null,
	Street_Address: if(row.PersonAddress_Address1 != null and row.PersonAddress_Address1 != "") row.PersonAddress_Address1 else "",
	Street_Address2: if ((row.PersonAddress_Address2 != null and row.PersonAddress_Address2 != "" )) row.PersonAddress_Address2 else " ",
	City_Address: row.PersonAddress_City default "",
	Zip_Code: row.PersonAddress_PostalCode default "",
	State: row.PersonAddress_StateCode default "",
	Phone: if ( (row.DenormEmployeeContact_MobilePhone as String default "") != "" ) row.DenormEmployeeContact_MobilePhone
  else if ( (row.DenormEmployeeContact_HomePhone as String default "") != "" ) row.DenormEmployeeContact_HomePhone
  else 
    "",
	Employee_Email: row.DenormEmployeeContact_BusinessEmail,
	Title: row.Job_ShortName,
	Race: row.Race,
	I9_Flag: row.I9Flag,
	Employee_Driver_License_Expire: (row.IdentificationExpiryDate as DateTime)  as String {
		format: "MM/dd/yyyy"
	} default null,
	Driver_license: row.IdentificationNumber,
//	Employee_Mobile_Phone: row.DenormEmployeeContact_HomePhone

}

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  errors: flatten(
            (if (vars.errorPayload..employeeRequiredImports != null) 
                vars.errorPayload..employeeRequiredImports 
             else []) 
            ++ 
            (if (vars.errorPayload..UpdateEmp_PersonalResponse != null) 
                vars.errorPayload..UpdateEmp_PersonalResponse 
             else [])
          )
}
